CREATE FUNCTION public.convite_auditar_confirmacao(_ator uuid,_usuario uuid,_convite uuid,_anterior text,_novo text,_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin(_ator) OR length(trim(_motivo))<10 THEN RAISE EXCEPTION 'Confirmação não autorizada'; END IF; IF NOT EXISTS(SELECT 1 FROM public.usuario_convites c JOIN auth.users u ON lower(trim(u.email))=lower(trim(c.email)) WHERE c.id=_convite AND u.id=_usuario AND lower(trim(c.email)) LIKE '%@liberdademedicaedu.com.br') THEN RAISE EXCEPTION 'Conta não corresponde ao convite corporativo'; END IF; INSERT INTO public.mt_auditoria(tabela,registro_id,campo,valor_anterior,valor_novo,alterado_por) VALUES('usuario_convites',_convite::text,'confirmacao_email_administrativa',_anterior,_novo||' · '||_motivo,_ator); END; $$; REVOKE ALL ON FUNCTION public.convite_auditar_confirmacao(uuid,uuid,uuid,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.convite_auditar_confirmacao(uuid,uuid,uuid,text,text,text) TO service_role;